CHECK(live.empty());

bool threw = false;
try { use_resource(1); } catch (const std::runtime_error&) { threw = true; }
CHECK(threw);
CHECK(live.empty());

for (int i = 0; i < 20; ++i) {
    try { use_resource(i % 3); } catch (const std::runtime_error&) {}
}
CHECK(live.empty());

